 public boolean active(){return mode!=null;}public boolean has(JSONObject m){return selected.contains(key(m));}
 public void toggle(JSONObject m){if(m.optString("kind").equals("deleted")||m.optBoolean("localFileDeleted"))return;if(mode==null)begin();String k=key(m);if(!selected.add(k))selected.remove(k);if(selected.isEmpty()&&mode!=null)mode.finish();else if(mode!=null)mode.setTitle(String.valueOf(selected.size()));refresh.run();}
 private ArrayList<JSONObject> chosen(){ArrayList<JSONObject> out=new ArrayList<>();JSONArray t=data();for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&selected.contains(key(m)))out.add(m);}return out;}
 public boolean onActionItemClicked(Mode m,int id){if(id==3){JSONArray t=data();for(int i=0;i<t.length();i++){JSONObject file=t.optJSONObject(i);if(file!=null&&!file.optBoolean("localFileDeleted")&&!file.optString("kind").equals("deleted")&&(source==null||file.optString("kind").equals("file")))selected.add(key(file));}m.setTitle(String.valueOf(selected.size()));refresh.run();return true;}ArrayList<JSONObject> messages=chosen();ArrayList<JSONObject> files=new ArrayList<>();StringBuilder body=new StringBuilder();for(JSONObject item:messages){if(item.optString("kind").equals("file"))files.add(item);else{if(body.length()>0)body.append("\n");body.append(item.optString("body"));}}final String text=body.toString();final Set<String> confirmedKeys=new HashSet<>();for(JSONObject file:messages)confirmedKeys.add(key(file));if(id==4){if(files.isEmpty()){if(!text.isEmpty()){Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,text);a.startActivity(Intent.createChooser(send,a.getString(R.string.share_other_apps)));}}else FileCards.shareMany(a,files,text);return true;}if(id==1){ForwardAction.show(a,messages,()->{m.finish();refresh.run();});return true;}

 if(id==2){Runnable remove=()->new AppDialog(a).setTitle(R.string.action_delete).setMessage(a.getString(messages.size()==1?R.string.remove_message_note:R.string.remove_messages_note,messages.size())).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.action_delete,(c,k)->{synchronized(Store.class){Store.saveThread(thread,ChatRules.removeMessages(Store.thread(thread),confirmedKeys));}m.finish();refresh.run();}).show();ArrayList<String> options=new ArrayList<>();options.add(a.getString(R.string.remove_selected_messages));if(!thread.startsWith("live_"))options.add(a.getString(R.string.delete_everyone));if(!files.isEmpty())options.add(a.getString(R.string.delete_local_files));new AppDialog(a).setTitle(R.string.action_delete).setItems(options.toArray(new String[0]),(d,n)->{if(n==0){remove.run();return;}if(!thread.startsWith("live_")&&n==1){RecallAction.show(a,thread,messages,()->{m.finish();refresh.run();});return;}new AppDialog(a).setTitle(R.string.action_delete).setMessage(a.getString(files.size()==1?R.string.delete_one_short:R.string.delete_many_short,files.size())).setNegativeButton(R.string.cancel,null).setPositiveButton(R.string.action_delete,(c,k)->{m.finish();deletion=new FileDelete(a,thread,files,refresh);deletion.start();}).show();}).show();return true;}return false;}
